/* limpeza de emojis iniciais em títulos/placeholder (padroniza ícones) */
const CX_EMO=/^[\p{Extended_Pictographic}️‍\s]+/u;
function cxCleanNode(root){
  try{
    root.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(i=>{const p=i.getAttribute('placeholder');if(p&&CX_EMO.test(p)){const n=p.replace(CX_EMO,'');if(n)i.setAttribute('placeholder',n);}});
    root.querySelectorAll('.section-title,.modal-title,.fin-section-title,.fin-dre-title,.stat-label,.fin-card-label').forEach(el=>{const t=el.firstChild;if(t&&t.nodeType===3&&CX_EMO.test(t.nodeValue)){const n=t.nodeValue.replace(CX_EMO,'');if(n)t.nodeValue=n;}});
  }catch(e){}
}
function cxCleanInit(){
  cxCleanNode(document);
  let tm=null;
  new MutationObserver(()=>{clearTimeout(tm);tm=setTimeout(()=>cxCleanNode(document),60);}).observe(document.body,{childList:true,subtree:true});
}
